<script setup>
/**
 * The Dogtastic mark.
 *
 * The source carried an inline <style> block defining .cls-1 and .cls-2.
 * SVG <style> applies to the whole document and Vue's scoped styles cannot
 * contain it, so those very generic class names would have leaked out. They
 * are attributes on the shapes now instead.
 *
 * Everything paints with currentColor, so the mark takes the colour of
 * whatever it sits in.
 */
</script>

<style scoped>
.brand-mark {
  display: block;
  width: 100%;
  height: auto;
}
</style>
